insert into public.missions(id,chapter_id,title,task,position) values('9-20','9','Финальный босс','Соберите проект по теме «Kubernetes: основы» без пошаговой подсказки. Покажите deploy, диагностику намеренной ошибки и восстановление. Сохраните README, код, тесты и независимую оценку по критериям: Типы, циклы, функции, файлы, исключения; CLI, API, логирование, тесты; Процессы, права, systemd, Bash; TCP/IP, DNS, HTTP, ветки и review; Образы, сети, volumes, Compose; Pipeline, артефакты, секреты, откат; Сервис, CI, документация, демонстрация; Диагностика и объяснение решений; Pod, Deployment, Service, probes.',20) on conflict(id) do nothing;
