insert into public.missions(id,chapter_id,title,task,position) values('16-20','16','Финальный босс','Соберите проект по теме «Комплексная инфраструктура» без пошаговой подсказки. Покажите deploy, диагностику намеренной ошибки и восстановление. Сохраните README, код, тесты и независимую оценку по критериям: Типы, циклы, функции, файлы, исключения; CLI, API, логирование, тесты; Процессы, права, systemd, Bash; TCP/IP, DNS, HTTP, ветки и review; Образы, сети, volumes, Compose; Pipeline, артефакты, секреты, откат; Сервис, CI, документация, демонстрация; Диагностика и объяснение решений; Pod, Deployment, Service, probes; Helm, RBAC, ресурсы, troubleshooting; State, модули, plan, IAM; Inventory, роли, идемпотентность; Метрики, логи, PromQL, алерты; SLO, runbook, incident, postmortem; Сканирование, least privilege, supply chain; IaC, GitOps, backup, disaster recovery.',20) on conflict(id) do nothing;
